  "sheet.somethingNeedsYouWhenItIsOwedToSomebody2": "欠项目之外的人事项，或记录状态表明工作中断时，就需要你处理。只有这两类。",
  "sheet.theOrderIsASumOfFiveFactorsWho": "排序分数由五项相加：谁受影响、谁在等待、逾期多久、有多少依据、已搁置多久。凡记录为可能伤人的事项，都排在其他事项之前，与双方分数无关。",
  "sheet.thisIsTheOneComponentInTheLibraryThat": "此组件在两种宽度使用不同结构。1440px 时直接显示段落，没有外框、折叠控件或计数行；390px 时用计数代替正文，按一下即可展开。无法读取宽度时会显示全部内容，不会凭猜测隐藏。",
  "sheet.countsThatAreQuestionsNotWork": "这些计数表示问题，而非要做的工作",
  "sheet.threeGroupsComeBackFromTheAttentionRuleThat": "待处理规则会另外返回三组：未分类的状态词、没有状态词的记录，以及主动暂停的工作。这里将它们显示为三个有名称的准确计数，每项都能打开完整列表。空组仍显示名称和零，但不能展开空白内容。",
  "sheet.stateWordsNobodyHasClassified": "尚未分类的状态词",
  "sheet.moleOfficeCannotTellWhetherTheseStoppedShortBecause": "Mole Office 无法确定这些工作是否中断，因为还没有人说明这些旧记录或导入记录中的状态词是什么意思。",
  "sheet.7Problems": "7 个问题",
  "sheet.9Ideas": "9 个想法",
  "sheet.3Purchases": "3 项采购",
  "sheet.2Tasks": "2 项任务",
  "sheet.recordsWithNoStateWord": "没有状态词的记录",
  "sheet.threeDifferentAnswersKeptApartAKindThatCarries": "区分三种答案：种类应有状态但未填写、种类根本没有状态字段，以及 Mole Office 不认识的种类。",
  "sheet.recordsOfKindSessionCarryAStateAndNone2": "session 种类应有状态，但这里未填写 — 9 条记录",
  "sheet.recordsOfKindNoteHaveNoStateFieldSo2": "note 种类没有状态字段，没有状态词可读 — 86 条记录",
  "sheet.moleOfficeDoesNotKnowTheKindTelemetrySo2": "Mole Office 不认识 telemetry 种类，无法确定是否应有状态 — 2 条记录",
  "sheet.putDownOnPurpose": "主动暂停",
  "sheet.aPauseIsADecisionNotAFailureSo": "暂停不等于失败，因此不列入待处理列表。每项都保留暂停原因，以及已记录的恢复条件。",
  "sheet.recordsOfAKindMoleOfficeDoesNotKnow": "Mole Office 不认识其种类的记录",
  "sheet.124RecordsThreeQuestionsAndOneAnswerOfNone": "124 条记录，三类问题，以及一组为零的答案。中间组默认展开以便拍照。空组只显示名称和计数；有成员时才显示说明并允许展开。",
  "sheet.theSameFactAtTheEmphasisTheSurfaceAsked": "同一事实，按页面所需的轻重显示",
  "sheet.aStateWordMeansOneThingEverywhereHowLoudly": "状态词的含义处处相同，显示轻重则取决于页面用途。主页供浏览，颜色强调紧急程度；运行、记录和查询页供比较，颜色回到状态本身，等级仍决定轻重。通过 surfaceEmphasis() 为页面声明一次。",
  "sheet.sixWordsThisInterfaceComputesEveryOneCarryingA": "界面计算的六种状态，每种都带等级。先看未作声明时的 perceptual 显示：",
  "sheet.theSameSixOnASurfaceThatDeclared": "同样六种状态，在声明了",
  "sheet.analytical": "analytical",
  "sheet.noStateHasChangedMeaningAndNoColourHas": "的页面上显示。状态含义与颜色都没改变：四个类别取回自身颜色，等级决定轻重。另两类不同：",
  "sheet.danger": "danger",
  "sheet.takesTheHueOnItsInkAndItsEdge": "只给文字与边缘上色，不填充背景，因为红色填充用于表示人可能受伤，而非进程终止。",
  "sheet.warning": "warning",
  "sheet.hasNoHueOfItsOwnToTakeSo": "没有自己的色相，所以使用正文颜色和空白背景。这些规则不改变记录中的词；存储词在各处使用同一种图形。",
  "sheet.theFamiliesGroupTheTenStatesTheyAreNot": "类别用于分组十种状态，并非第十一种状态。分析式页面因此可以把颜色还给",
  "sheet.crashed": "crashed",
  "sheet.andWithholdItFrom": "，而不给",
  "sheet.open": "open",
  "sheet.whichIsTheDifferenceBetweenACatalogueAndAn": "，这就是目录与警报的区别。",
  "sheet.aRecordsListIsTheCaseThatMustNot": "记录列表不应看起来像警报：下面每个词都保存在记录中，它们并不都表示故障。先显示 perceptual，再显示 analytical。未指定等级的词不再借用警报色；带等级的词改用正文颜色，不再沿用中性类别的灰色。这样可以区分存储词",
  "sheet.idle": "idle",
  "sheet.andASessionThatIsIdleCameOutAs": "和处于空闲状态的运行。轻重由笔画和整行决定，其中",
  "sheet.raised": "raised",
  "sheet.oneIsStillTheHeavierStrokeAndTheLast": "的笔画仍较重，最后两级则画法相同。恢复类别自身颜色会产生这种效果。",
