  "g2b.impl.refused.observed_write": "Mole Office 不运行 git，有一个测试保证这一点。替代它的办法对关键问题是精确的——比较两次构建的 source_file_hashes 就能准确得知哪些文件变了——但观察到一次写入本身并不产生关系：“某个 agent 说自己在做 Perception 时这些文件变了”只是相关。生成器还会把机器写的行填进一张由人编写、会导出、有变更日志的表里；文件索引不放进 `records`，正是为了避免这种淹没。",
