  'record.hint.merge_entry.run': "提交这条记录的运行。提交时它带着一份封存凭据。",
  'record.hint.merge_entry.state': "这条记录在合并队列里进行到哪一步。哪一步能接哪一步由办公室决定，不由提交的人决定。",
  'record.hint.merge_entry.occupies': "这条记录此刻占用的通道，也就是它要落入的目录。办公室在写状态时一并写入；同一条通道只能有一条记录占用；留空表示没有占用。",
  'record.hint.merge_entry.attempts': "这条记录在测试或落地期间，主世界在它之下变动过多少次，因而被退回重审。从未发生过就留空。",
  'record.hint.module.context': "这个模块为什么存在，写几句话。写理由，不要写它做什么的说明：说清没有它会出什么问题。",
  'record.hint.module.state': "这个子系统目前处于什么状态，用一个词表示。“{active}”：有人在推进。“{paused}”：有意搁下，原因和恢复条件写在暂停说明里。“{stable}”：现有实现够当前用途使用，需要再动时回到“{active}”。“{retired}”：已不再使用，但记录留着，依赖它的东西仍能找到。这个词不说明完成了多少。没人说明就留空；留空与这四种都不同。",
  'record.hint.module.summary': "一段话，说明不打开完整报告也值得知道的内容。这是模块页顶部的那一段，不是在别处提到这个模块时显示的一行摘要。",
  'record.hint.module.source': "如果这是从别处取来的，这里说明出处：某个文件与章节、一段讨论串、一篇论文或一次运行。这样不在场的人也能核对这条记录。",
  'record.hint.pipeline.dependenciesComplete': "在有人核对过每一步所等待的都已作为连接写下之后，才选“是”。在那之前留空，因为留空是一个真实答案，和“否”不同：“是”表示这些空缺是有意为之，“否”表示有人发现连接还没写完，留空表示没人说过。",
  'record.hint.pipeline.source': "如果这是从别处取来的，这里说明出处：某个文件与章节、一段讨论串、一篇论文或一次运行。这样不在场的人也能核对这条记录。",
  'record.hint.block.state': "这个环节进行到哪一步。主页和流水线页靠它指出流水线正卡在哪个环节，提醒规则也靠它找出哪项工作半途停了。",
  'record.hint.block.measured': "在这个环节上测到了什么，用当时的计量单位写。什么都没测就留空。",
  'record.hint.block.method': "这一步本该做什么，写清楚到别人能判断它有没有运行。实际改用的方法不写在这里，也绝不改写它；在这种替代还在生效期间，只有本人能改这一项。",
  'record.hint.block.effort_hours': "这个环节大约要多少小时，写数字：0.5 是半小时，6 是一整天。没人估过就留空；留空不等于 0。",
  'record.hint.block.source': "如果这是从别处取来的，这里说明出处：某个文件与章节、一段讨论串、一篇论文或一次运行。这样不在场的人也能核对这条记录。",
  'record.hint.session.executionId': "这次提交的尝试属于哪一次执行，前提是当时记下了。",
  'record.hint.session.attemptId': "提交的是哪一次尝试，前提是当时记下了。",
  'record.hint.session.resourcesLookDueAt': "办公室打算何时再查看这次运行的资源。只有运行结束时还有未了结的事才会写入，查看过后就抹去；更早的运行没有这一项。",
  'record.hint.session.sealedTip': "运行结束时办公室写下的封存凭据，之后不会改变。",
  'record.hint.session.state': "这次运行进行到哪一步。“{running}”：最近几分钟有输出。“{idle}”：还活着但很久没说话，通常在等你。“{finished}”：正常退出。“{crashed}”：没完成就停了。“{paused}”：办公室关机时特意停下并保留了会话，不会自己继续。“{orphaned}”：已经没有人接管，但仍在运行。“{unknown}”：办公室判断不出来。没有它，这条记录就不完整，因为读不出状态的运行无法在告警面板上排序。",
  'record.hint.session.runtime': "是哪个工具运行了这个进程，例如 claude-code 或 codex-cli。它和智能体的运行环境用同一个词，因为是同一件事。",
  'record.hint.session.adaptedTool': "在办公室适配的工具里，是哪一个运行了这次运行，由启动或登记它的一方说明。没人说明就留空，之后会按“未说明”统计，而不会去猜。",
  'record.hint.session.ranProgram': "实际运行的程序在机器上的完整路径，因为同一台机器可能装了两份同一个工具，只写名字说不清是哪一份。没人记录就留空。",
  'record.hint.session.ranProgramVersion': "那个程序自己说出的版本。读不到版本时，这里改存说明原因的句子，因为这是两回事。没人问过就留空。",
  'record.hint.session.model': "这次运行被指定的模型，用工具收到的原话写。没人记录就留空，2026 年 9 月 8 日之前启动的运行都是这样。它不是价格。",
  'record.hint.session.effort': "这次运行被指定的投入程度，用运行自己说的词写。运行没说就留空；留空不是中等，也不是默认值。",
  'record.hint.session.doing': "它正在做什么，或者停下时在做什么，写一行。",
  'record.hint.session.lastOutputAt': "它最后一次产生输出的时间，按本地时间写。空闲时长就是照着它算的；不要填“现在”，留空即可，系统会改用记录自己的最后修改时间。",
